export type BuyerQuoteTaxBasis = typeof BuyerQuoteTaxBasis[keyof typeof BuyerQuoteTaxBasis];


export const BuyerQuoteTaxBasis = {
  ex_gst: 'ex_gst',
  inc_gst: 'inc_gst',
} as const;

/**
 * Buyer-entered terms linked to a private written quote, not independently verified.
 */
