/**
 * Idempotency key or draft-version conflict
 */
export type ConflictResponse = ErrorResponse;

/**
 * Minute rate limit exceeded
 */
export type RateLimitedResponse = ErrorResponse;

/**
 * Prepaid comparison allowance exhausted
 */
